// === Tab: mySketch ===
const vs = `
attribute vec3 aPosition;
attribute vec4 aMaterialColor;
attribute vec3 aNoiseArray;
attribute vec2 aTexCoord;

uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;

varying vec4 vColor;
varying vec2 vTexCoord;

uniform float uMixcoef;

void main(void) {
   vec3 position = aPosition + aNoiseArray * uMixcoef;
   gl_Position = uProjectionMatrix * uModelViewMatrix * vec4(position, 1.0);
   vColor = aMaterialColor;
   vTexCoord = aTexCoord;
}
`;

const fs = `
precision highp float;

varying vec4 vColor;

varying vec2 vTexCoord;
uniform sampler2D u_tex;

void main(void) {
   vec2 uv = vTexCoord;
   vec4 tex = texture2D(u_tex, uv);

   //gl_FragColor = vec4(vColor.rgb*0.3+ tex.rgb*0.8, vColor.w) ;
   gl_FragColor = tex ;
}
`;

const w = 1112;
const fps = 20;
const P = 256;
const l = w/3.75;
let theShader;

function setup() {

    setAttributes("alpha", false);
    setAttributes("antialias", true);

   _gl = createCanvas(w, w * .75, WEBGL);
   frameRate(fps);

   colorMode(HSB);
   noStroke();

   theShader = createShader(vs, fs);
   _gl.retainedMode.buffers.fill.push(new p5.RenderBuffer(3, "noiseArray", "noiseBuffer", "aNoiseArray", _gl));

	 gl = this._renderer.GL;
   gl.enable(gl.CULL_FACE);

	 let seed_set = int(random(0,10000));
	 randomSeed(seed_set);
	 noiseSeed(seed_set);

	 xs = random([-1,1]);
	 ys = random([-1,1]);

	 tex = createGraphics(w,w);
	 tex.noStroke();
	 tex.colorMode(HSB);
	 tex.background(100,0.2);

	 let c = [set_color(), set_color(), set_color(), set_color()];
	 for(let i=0;i<500;i++){
		 tex.fill(...random(c), random());
	   tex.rect(random(w), random(w), random(w/48, w/16), random(w/48, w/16));
	 }

}

function draw() {
   shader(theShader);
   theShader.setUniform('uMixcoef', 0.5-0.5*cos(frameCount/(fps*3)));
	 theShader.setUniform("u_tex", tex);

   background(0);
   push();
	 fill(100, 0.1);
   rotateX(xs*frameCount/(fps*8));
   rotateY(ys*frameCount/(fps*3));
   translate(0, 0, 0);

   gl.cullFace(gl.BACK);
   noisy_sphere(l, P, P);
   gl.cullFace(gl.FRONT);
   noisy_sphere(l, P, P);
   pop();

   resetShader();
}

function set_color(){
   return [random(150, 220), random(30,100), random(80,100)];
}

function noisy_sphere(size, detailX, detailY) {
   const gId = `noisy_sphere|${size}|${detailX}|${detailY}`;

   if (!this._renderer.geometryInHash(gId)) {
      let geom = new p5.Geometry(detailX, detailY);
      geom.noiseArray = [];

       let dd = 0.5;
       let weight = 0.033;
       let p0 = [];
       let k=random();

       for (var i = 0; i <= detailY; i++) {
         var v = i / detailY;
         var phi = Math.PI * v - Math.PI / 2;
         var cosPhi = Math.cos(phi);
         var sinPhi = Math.sin(phi);

         for (var j = 0; j <= detailX; j++) {
           var u = j / detailX;
           var theta = 2 * Math.PI * u;
           var cosTheta = Math.cos(theta);
           var sinTheta = Math.sin(theta);
           var p = new p5.Vector(
             cosPhi * sinTheta,
             sinPhi,
             cosPhi * cosTheta
           );
           geom.vertices.push(p);
           geom.uvs.push(u, v);

					 let ii = abs(i-detailX/2);
					 let jj = abs(j-detailY/2);
					 n = dd*(sin(TAU*noise(ii*weight, jj*weight, k)));
           p = [cosPhi * sinTheta * n + sin(i/20)*0.2,
                sinPhi * n,
                cosPhi * cosTheta * n + cos(j/20)*0.2							 
							 ];

           if(j==0){p0=p;}
           if(j==detailX || i==0 || i==detailY){p=p0;}
           geom.noiseArray.push(...p);

           geom.vertexColors.push(0.1+random(0.1),
            0.8+abs(sin((i-detailX/2)/15 +random(0.25)))*0.2+0.5*p[1],
            0.8+abs(cos((j-detailY/2)/21 +random(0.3)))*0.4+0.6*p[2] +sin(ii/5)*0.1,
            0.75);
         }
       }

     geom.computeFaces();
     geom.computeNormals();
     geom._makeTriangleEdges()._edgesToVertices();
     this._renderer.createBuffers(gId, geom);
   }
   this._renderer.drawBuffersScaled(gId, size, size, size);
}

